svg.script:

(function () {
  const state = {
    currentZone: 'bedroom', // 'bedroom' | 'balcony' | 'bathroom'
    x: 480,
    y: 280,
    speed: 4.2,
    facing: 'down',
    isMoving: false,
    walkCycle: 0,
    transitioning: false,

    computerPowered: true,
    isNearComputer: false,
    modalOpen: false,

    // Proximity Door State
    activeDoor: null, // Holds the door data if player is within interaction distance

    keys: {
      w: false, a: false, s: false, d: false,
      up: false, down: false, left: false, right: false
    }
  };

  // Room-specific boundaries, obstacles, and doors
  const ROOM_DATA = {
    bedroom: {
      bounds: { minX: 100, maxX: 860, minY: 85, maxY: 555 },
      obstacles: [
        { x: 80, y: 70, w: 145, h: 145 }, // Desk
        { x: 235, y: 115, w: 45, h: 55 }, // Chair
        { x: 80, y: 240, w: 350, h: 165 }, // Bed
        { x: 80, y: 425, w: 120, h: 120 }, // Nightstand
        { x: 715, y: 70, w: 165, h: 180 }, // Wardrobe
        // Top Walls (Door gap at X: 430 to 530, but solid until E pressed)
        { x: 75, y: 55, w: 810, h: 25 },
        // Bottom Walls
        { x: 75, y: 560, w: 810, h: 25 },
        // Right Wall
        { x: 865, y: 60, w: 25, h: 260 },
        { x: 865, y: 440, w: 25, h: 140 }
      ],
      computerHotspot: { x: 210, y: 140, radius: 100 },
      doors: [
        {
          id: 'balcony-door',
          promptEl: 'prompt-balcony-door',
          hotspot: { x: 480, y: 95, radius: 55 },
          targetZone: 'balcony',
          spawnX: 480,
          spawnY: 490
        },
        {
          id: 'bathroom-door',
          promptEl: 'prompt-bathroom-door',
          hotspot: { x: 480, y: 535, radius: 55 },
          targetZone: 'bathroom',
          spawnX: 480,
          spawnY: 240
        },
        {
          id: 'livingroom-door',
          promptEl: 'prompt-livingroom-door',
          hotspot: { x: 840, y: 380, radius: 55 },
          targetZone: 'livingroom',
          spawnX: 135,
          spawnY: 380
        }
      ]
    },

    balcony: {
      bounds: { minX: 115, maxX: 845, minY: 305, maxY: 535 },
      obstacles: [
        { x: 90, y: 280, w: 780, h: 25 },
        { x: 90, y: 280, w: 25, h: 280 },
        { x: 845, y: 280, w: 25, h: 280 },
        { x: 120, y: 350, w: 45, h: 50 },
        { x: 90, y: 540, w: 780, h: 25 } // Bottom railing/wall
      ],
      doors: [
        {
          id: 'balcony-exit',
          promptEl: 'prompt-balcony-exit',
          hotspot: { x: 480, y: 510, radius: 55 },
          targetZone: 'bedroom',
          spawnX: 480,
          spawnY: 115
        }
      ]
    },

    // Remastered Architectural En-Suite Bathroom (Wide Layout per Sketch)
    bathroom: {
      bounds: { minX: 145, maxX: 810, minY: 205, maxY: 428 },
      obstacles: [
        // Vertical Bathtub Enclosure on Left Wall (X: 144 to 258, Y: 195 to 435)
        { x: 140, y: 195, w: 120, h: 245 },
        // Washing Machine, Privacy Divider & Vanity Sink along Top Wall (X: 615 to 818, Y: 195 to 270)
        { x: 610, y: 195, w: 210, h: 80 },
        // Luxury Toilet Suite in Bottom-Right Corner (X: 730 to 812, Y: 355 to 435)
        { x: 725, y: 355, w: 90, h: 80 },
        // Top Perimeter Walls Flanking Doorway (Doorway at X: 440 to 520)
        { x: 132, y: 180, w: 308, h: 25 },
        { x: 520, y: 180, w: 308, h: 25 },
        // Bottom Perimeter Wall
        { x: 132, y: 432, w: 696, h: 25 }
      ],
      doors: [
        {
          id: 'bathroom-exit',
          promptEl: 'prompt-bathroom-exit',
          hotspot: { x: 480, y: 215, radius: 55 },
          targetZone: 'bedroom',
          spawnX: 480,
          spawnY: 505
        }
      ]
    },

    // Modern Apartment Living Room
    livingroom: {
      bounds: { minX: 100, maxX: 860, minY: 85, maxY: 555 },
      obstacles: [
        // Kitchen Island + Barstools (X: 165 to 345, Y: 92 to 157, stools to 178)
        { x: 160, y: 70, w: 190, h: 115 },
        // Dining Table + Chairs (Table X: 175 to 295, Chairs: Y: 418 to 532, X: 148 to 322)
        { x: 148, y: 418, w: 176, h: 120 },
        // Rebuilt Workstation Furniture & Chair (X: 570 to 735, Y: 72 to 118, chair down to 146)
        { x: 565, y: 70, w: 175, h: 80 },
        // Sectional Sofa Main Row (X: 505 to 735, Y: 260 to 316)
        { x: 500, y: 255, w: 240, h: 65 },
        // Sectional Sofa Chaise Return (X: 505 to 565, Y: 185 to 260)
        { x: 500, y: 180, w: 70, h: 80 },
        // Coffee Table (X: 585 to 685, Y: 195 to 240)
        { x: 580, y: 190, w: 110, h: 55 },
        // Lounge Armchair (X: 715 to 762, Y: 185 to 232)
        { x: 710, y: 180, w: 58, h: 58 },
        // Monstera Plant in Bottom-Right Corner (X: 815, Y: 495)
        { x: 795, y: 475, w: 45, h: 50 },
        // Foyer Console Table (X: 84 to 108, Y: 235 to 307)
        { x: 75, y: 230, w: 35, h: 80 },
        // Top Perimeter Wall
        { x: 65, y: 50, w: 830, h: 25 },
        // Bottom Perimeter Wall Flanking Balcony Doors
        { x: 65, y: 560, w: 385, h: 25 },
        { x: 800, y: 560, w: 95, h: 25 },
        // Right Perimeter Wall
        { x: 865, y: 50, w: 25, h: 540 },
        // Left Perimeter Wall (North of Door)
        { x: 65, y: 50, w: 25, h: 275 },
        // Left Perimeter Wall (South of Door)
        { x: 65, y: 430, w: 25, h: 160 }
      ],
      workstationHotspot: { x: 652, y: 135, radius: 75 },
      doors: [
        {
          id: 'livingroom-exit',
          promptEl: 'prompt-living-exit',
          hotspot: { x: 135, y: 380, radius: 55 },
          targetZone: 'bedroom',
          spawnX: 835,
          spawnY: 380
        }
      ]
    }
  };

  // DOM Elements
  const svg = document.getElementById('game-svg');
  const playerEl = document.getElementById('player');
  const legLEl = document.getElementById('leg-l');
  const legREl = document.getElementById('leg-r');
  const shoeLEl = document.getElementById('shoe-l');
  const shoeREl = document.getElementById('shoe-r');
  const armLEl = document.getElementById('arm-l');
  const armREl = document.getElementById('arm-r');
  const headEl = document.getElementById('head');
  const eyesEl = document.getElementById('eyes');
  const shirtCollarEl = document.getElementById('shirt-collar');
  const tieEl = document.getElementById('tie');
  const lapelLEl = document.getElementById('lapel-l');
  const lapelREl = document.getElementById('lapel-r');
  const suitBtn1El = document.getElementById('suit-btn-1');
  const suitBtn2El = document.getElementById('suit-btn-2');

  const roomBedroomEl = document.getElementById('room-bedroom');
  const roomBalconyEl = document.getElementById('room-balcony');
  const roomBathroomEl = document.getElementById('room-bathroom');
  const roomLivingRoomEl = document.getElementById('room-livingroom');
  const locationLabel = document.getElementById('location-label');

  const interactPrompt = document.getElementById('interact-prompt');
  const computerModal = document.getElementById('computer-modal');
  const modalBackdrop = document.getElementById('modal-backdrop');
  const btnCloseModal = document.getElementById('btn-close-modal');
  const btnCloseDot = document.getElementById('btn-close-dot');
  const btnShutdown = document.getElementById('btn-shutdown');
  const btnPowerOn = document.getElementById('btn-power-on');
  const modalOnlineView = document.getElementById('modal-online-view');
  const modalOfflineView = document.getElementById('modal-offline-view');

  const screenDisplay = document.getElementById('screen-display');
  const screenContent = document.getElementById('screen-content');
  const screenOffContent = document.getElementById('screen-off-content');
  const screenGlow = document.getElementById('screen-glow');
  const monitorLed = document.getElementById('monitor-led');
  const powerLed = document.getElementById('power-led');
  const powerLedGlow = document.getElementById('power-led-glow');
  const computerStation = document.getElementById('computer-screen-station');

  // Door prompt DOM elements
  const promptBalconyDoor = document.getElementById('prompt-balcony-door');
  const promptBathroomDoor = document.getElementById('prompt-bathroom-door');
  const promptLivingDoor = document.getElementById('prompt-livingroom-door');
  const promptBalconyExit = document.getElementById('prompt-balcony-exit');
  const promptBathroomExit = document.getElementById('prompt-bathroom-exit');
  const promptLivingExit = document.getElementById('prompt-living-exit');
  const promptLivingWorkstation = document.getElementById('prompt-living-workstation');
  const livingWorkstationEl = document.getElementById('living-entertainment');

  const promptMap = {
    'prompt-balcony-door': promptBalconyDoor,
    'prompt-bathroom-door': promptBathroomDoor,
    'prompt-livingroom-door': promptLivingDoor,
    'prompt-balcony-exit': promptBalconyExit,
    'prompt-bathroom-exit': promptBathroomExit,
    'prompt-living-exit': promptLivingExit
  };

  // Door element click listeners (only work when near!)
  const doorToBalcony = document.getElementById('door-to-balcony');
  const doorToBathroom = document.getElementById('door-to-bathroom');
  const doorToLiving = document.getElementById('door-to-livingroom');
  const exitBalcony = document.getElementById('exit-balcony-to-room');
  const exitBathroom = document.getElementById('exit-bathroom-to-room');
  const exitLiving = document.getElementById('exit-living-to-room');

  // Audio Synthesizer
  function playTone(freq, duration, type = 'sine') {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + duration);
    } catch (e) {}
  }

  function playDoorSound() {
    playTone(320, 0.08, 'triangle');
    setTimeout(() => playTone(480, 0.12, 'triangle'), 80);
  }

  function playPowerDownSound() {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(440, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(55, ctx.currentTime + 0.6);
      gain.gain.setValueAtTime(0.15, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.6);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.6);
    } catch (e) {}
  }

  function playPowerUpSound() {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(110, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.4);
      gain.gain.setValueAtTime(0.12, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.4);
    } catch (e) {}
  }

  // Room Transition Function
  function switchRoom(targetZone, spawnX, spawnY) {
    if (state.transitioning) return;
    state.transitioning = true;
    playDoorSound();

    // Hide all prompts
    hideAllDoorPrompts();

    // Update State
    state.currentZone = targetZone;
    state.x = spawnX;
    state.y = spawnY;
    state.activeDoor = null;

    // Hide all room layers
    roomBedroomEl.style.display = 'none';
    roomBalconyEl.style.display = 'none';
    roomBathroomEl.style.display = 'none';
    roomLivingRoomEl.style.display = 'none';

    // Show targeted room layer only
    if (targetZone === 'bedroom') {
      roomBedroomEl.style.display = 'block';
      locationLabel.textContent = 'BEDROOM';
      locationLabel.setAttribute('fill', '#00ffff');
    } else if (targetZone === 'balcony') {
      roomBalconyEl.style.display = 'block';
      locationLabel.textContent = 'BALCONY (CITY VIEW)';
      locationLabel.setAttribute('fill', '#7dd3fc');
    } else if (targetZone === 'bathroom') {
      roomBathroomEl.style.display = 'block';
      locationLabel.textContent = 'BATHROOM (REMASTERED)';
      locationLabel.setAttribute('fill', '#38ef7d');
    } else if (targetZone === 'livingroom') {
      roomLivingRoomEl.style.display = 'block';
      locationLabel.textContent = 'LIVING ROOM';
      locationLabel.setAttribute('fill', '#ffd166');
    }

    state.keys.w = state.keys.a = state.keys.s = state.keys.d = false;
    state.keys.up = state.keys.left = state.keys.down = state.keys.right = false;

    playerEl.setAttribute('transform', `translate(${state.x}, ${state.y})`);

    setTimeout(() => {
      state.transitioning = false;
      updateProximity();
    }, 220);
  }

  function hideAllDoorPrompts() {
    if (promptBalconyDoor) promptBalconyDoor.style.display = 'none';
    if (promptBathroomDoor) promptBathroomDoor.style.display = 'none';
    if (promptLivingDoor) promptLivingDoor.style.display = 'none';
    if (promptBalconyExit) promptBalconyExit.style.display = 'none';
    if (promptBathroomExit) promptBathroomExit.style.display = 'none';
    if (promptLivingExit) promptLivingExit.style.display = 'none';
    if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
  }

  // Check Proximity for Doors (Requires [E] to enter)
  function updateDoorProximity() {
    if (state.transitioning) return;
    const currentData = ROOM_DATA[state.currentZone];
    if (!currentData || !currentData.doors) {
      state.activeDoor = null;
      hideAllDoorPrompts();
      return;
    }

    let foundDoor = null;

    for (let i = 0; i < currentData.doors.length; i++) {
      const door = currentData.doors[i];
      const dx = state.x - door.hotspot.x;
      const dy = state.y - door.hotspot.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < door.hotspot.radius) {
        foundDoor = door;
        break;
      }
    }

    // Update active door & UI badge
    hideAllDoorPrompts();
    state.activeDoor = foundDoor;

    if (foundDoor && foundDoor.promptEl) {
      const pEl = promptMap[foundDoor.promptEl];
      if (pEl) pEl.style.display = 'block';
    }
  }

  // Check Proximity to Desk/Computer/Workstation
  function updateProximity() {
    if (state.currentZone === 'bedroom') {
      const hotspot = ROOM_DATA.bedroom.computerHotspot;
      const dx = state.x - hotspot.x;
      const dy = state.y - hotspot.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      state.isNearComputer = dist < hotspot.radius;

      if (state.isNearComputer && !state.modalOpen) {
        interactPrompt.style.display = 'block';
      } else {
        interactPrompt.style.display = 'none';
      }
      if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
    } else if (state.currentZone === 'livingroom') {
      interactPrompt.style.display = 'none';
      const hotspot = ROOM_DATA.livingroom.workstationHotspot;
      if (hotspot) {
        const dx = state.x - hotspot.x;
        const dy = state.y - hotspot.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        state.isNearComputer = dist < hotspot.radius;

        if (promptLivingWorkstation) {
          if (state.isNearComputer && !state.modalOpen) {
            promptLivingWorkstation.style.display = 'block';
          } else {
            promptLivingWorkstation.style.display = 'none';
          }
        }
      } else {
        state.isNearComputer = false;
        if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
      }
    } else {
      interactPrompt.style.display = 'none';
      if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
      state.isNearComputer = false;
    }

    updateDoorProximity();
  }

  // Open / Close Computer OS Modal
  function openComputerModal() {
    if (state.currentZone !== 'bedroom' && state.currentZone !== 'livingroom') return;
    state.modalOpen = true;
    interactPrompt.style.display = 'none';
    if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
    computerModal.style.display = 'block';
    playTone(600, 0.1);
  }

  function closeComputerModal() {
    state.modalOpen = false;
    computerModal.style.display = 'none';
    updateProximity();
    playTone(400, 0.08);
    if (svg) svg.focus();
  }

  function shutDownComputer() {
    playPowerDownSound();
    state.computerPowered = false;

    screenDisplay.setAttribute('stroke', '#333b4d');
    screenContent.style.display = 'none';
    screenOffContent.style.display = 'block';
    screenGlow.style.display = 'none';
    monitorLed.setAttribute('fill', '#333b4d');
    powerLed.setAttribute('fill', '#484f58');
    powerLedGlow.style.display = 'none';

    modalOnlineView.style.display = 'none';
    modalOfflineView.style.display = 'block';
  }

  function powerOnComputer() {
    playPowerUpSound();
    state.computerPowered = true;

    screenDisplay.setAttribute('stroke', '#00ffff');
    screenContent.style.display = 'block';
    screenOffContent.style.display = 'none';
    screenGlow.style.display = 'block';
    monitorLed.setAttribute('fill', '#00ffff');
    powerLed.setAttribute('fill', '#00ffff');
    powerLedGlow.style.display = 'block';

    modalOnlineView.style.display = 'block';
    modalOfflineView.style.display = 'none';
  }

  // Collision Detection per active room
  function checkCollision(nx, ny) {
    const charRadius = 15;
    const currentData = ROOM_DATA[state.currentZone];
    if (!currentData) return false;

    if (nx - charRadius < currentData.bounds.minX || nx + charRadius > currentData.bounds.maxX) return true;
    if (ny - 5 < currentData.bounds.minY || ny + 20 > currentData.bounds.maxY) return true;

    for (let i = 0; i < currentData.obstacles.length; i++) {
      const obs = currentData.obstacles[i];
      if (
        nx + charRadius > obs.x &&
        nx - charRadius < obs.x + obs.w &&
        ny + 15 > obs.y &&
        ny - 10 < obs.y + obs.h
      ) {
        return true;
      }
    }
    return false;
  }

  // Input Event Listeners
  function handleKeyDown(e) {
    if (e.key === 'Escape') {
      if (state.modalOpen) {
        closeComputerModal();
        return;
      }
    }

    const key = e.key ? e.key.toLowerCase() : '';

    // [E] KEY ACTION: Check Door Transition FIRST or Computer Interaction
    if (key === 'e' || key === ' ' || key === 'enter' || e.code === 'KeyE' || e.code === 'Space' || e.code === 'Enter') {
      // 1. Door Transition (only when near!)
      if (state.activeDoor && !state.modalOpen) {
        e.preventDefault();
        switchRoom(state.activeDoor.targetZone, state.activeDoor.spawnX, state.activeDoor.spawnY);
        return;
      }

      // 2. Computer Interaction (only when near in bedroom!)
      if (state.isNearComputer && !state.modalOpen) {
        e.preventDefault();
        openComputerModal();
        return;
      }
    }

    if (state.modalOpen) return;

    if (key === 'w' || e.code === 'KeyW') { state.keys.w = true; e.preventDefault(); }
    if (key === 's' || e.code === 'KeyS') { state.keys.s = true; e.preventDefault(); }
    if (key === 'a' || e.code === 'KeyA') { state.keys.a = true; e.preventDefault(); }
    if (key === 'd' || e.code === 'KeyD') { state.keys.d = true; e.preventDefault(); }
    if (key === 'arrowup' || e.code === 'ArrowUp') { state.keys.up = true; e.preventDefault(); }
    if (key === 'arrowdown' || e.code === 'ArrowDown') { state.keys.down = true; e.preventDefault(); }
    if (key === 'arrowleft' || e.code === 'ArrowLeft') { state.keys.left = true; e.preventDefault(); }
    if (key === 'arrowright' || e.code === 'ArrowRight') { state.keys.right = true; e.preventDefault(); }
  }

  function handleKeyUp(e) {
    const key = e.key ? e.key.toLowerCase() : '';
    if (key === 'w' || e.code === 'KeyW') state.keys.w = false;
    if (key === 's' || e.code === 'KeyS') state.keys.s = false;
    if (key === 'a' || e.code === 'KeyA') state.keys.a = false;
    if (key === 'd' || e.code === 'KeyD') state.keys.d = false;
    if (key === 'arrowup' || e.code === 'ArrowUp') state.keys.up = false;
    if (key === 'arrowdown' || e.code === 'ArrowDown') state.keys.down = false;
    if (key === 'arrowleft' || e.code === 'ArrowLeft') state.keys.left = false;
    if (key === 'arrowright' || e.code === 'ArrowRight') state.keys.right = false;
  }

  // Click Listeners (Strictly Require Proximity!)
  if (interactPrompt) interactPrompt.addEventListener('click', openComputerModal);
  if (computerStation) {
    computerStation.addEventListener('click', function () {
      if (state.isNearComputer && !state.modalOpen) {
        openComputerModal();
      }
    });
  }

  // Door Clicks: ONLY triggered if player is already near the door!
  function handleDoorClick(doorId) {
    if (state.activeDoor && state.activeDoor.id === doorId && !state.modalOpen) {
      switchRoom(state.activeDoor.targetZone, state.activeDoor.spawnX, state.activeDoor.spawnY);
    }
  }

  if (doorToBalcony) doorToBalcony.addEventListener('click', () => handleDoorClick('balcony-door'));
  if (doorToBathroom) doorToBathroom.addEventListener('click', () => handleDoorClick('bathroom-door'));
  if (doorToLiving) doorToLiving.addEventListener('click', () => handleDoorClick('livingroom-door'));
  if (exitBalcony) exitBalcony.addEventListener('click', () => handleDoorClick('balcony-exit'));
  if (exitBathroom) exitBathroom.addEventListener('click', () => handleDoorClick('bathroom-exit'));
  if (exitLiving) exitLiving.addEventListener('click', () => handleDoorClick('livingroom-exit'));

  if (promptBalconyDoor) promptBalconyDoor.addEventListener('click', () => handleDoorClick('balcony-door'));
  if (promptBathroomDoor) promptBathroomDoor.addEventListener('click', () => handleDoorClick('bathroom-door'));
  if (promptLivingDoor) promptLivingDoor.addEventListener('click', () => handleDoorClick('livingroom-door'));
  if (promptBalconyExit) promptBalconyExit.addEventListener('click', () => handleDoorClick('balcony-exit'));
  if (promptBathroomExit) promptBathroomExit.addEventListener('click', () => handleDoorClick('bathroom-exit'));
  if (promptLivingExit) promptLivingExit.addEventListener('click', () => handleDoorClick('livingroom-exit'));
  if (promptLivingWorkstation) {
    promptLivingWorkstation.addEventListener('click', function () {
      if (state.isNearComputer && !state.modalOpen) {
        openComputerModal();
      }
    });
  }
  if (livingWorkstationEl) {
    livingWorkstationEl.addEventListener('click', function () {
      if (state.isNearComputer && !state.modalOpen) {
        openComputerModal();
      }
    });
  }

  if (btnCloseModal) btnCloseModal.addEventListener('click', closeComputerModal);
  if (btnCloseDot) btnCloseDot.addEventListener('click', closeComputerModal);
  if (modalBackdrop) modalBackdrop.addEventListener('click', closeComputerModal);
  if (btnShutdown) btnShutdown.addEventListener('click', shutDownComputer);
  if (btnPowerOn) btnPowerOn.addEventListener('click', powerOnComputer);

  window.addEventListener('keydown', handleKeyDown);
  window.addEventListener('keyup', handleKeyUp);
  svg.addEventListener('click', function () { svg.focus(); });
  svg.focus();

  function updateCharacterFacing(facing) {
    if (facing === 'up') {
      eyesEl.style.display = 'none';
      shirtCollarEl.style.display = 'none';
      tieEl.style.display = 'none';
      lapelLEl.style.display = 'none';
      lapelREl.style.display = 'none';
      suitBtn1El.style.display = 'none';
      suitBtn2El.style.display = 'none';
    } else if (facing === 'down') {
      eyesEl.style.display = 'block';
      shirtCollarEl.style.display = 'block';
      tieEl.style.display = 'block';
      lapelLEl.style.display = 'block';
      lapelREl.style.display = 'block';
      suitBtn1El.style.display = 'block';
      suitBtn2El.style.display = 'block';
      playerEl.querySelector('#player-visual').setAttribute('transform', 'scale(1, 1)');
    } else if (facing === 'left') {
      eyesEl.style.display = 'block';
      shirtCollarEl.style.display = 'block';
      tieEl.style.display = 'block';
      lapelLEl.style.display = 'block';
      lapelREl.style.display = 'block';
      suitBtn1El.style.display = 'block';
      suitBtn2El.style.display = 'block';
      playerEl.querySelector('#player-visual').setAttribute('transform', 'scale(-1, 1)');
    } else if (facing === 'right') {
      eyesEl.style.display = 'block';
      shirtCollarEl.style.display = 'block';
      tieEl.style.display = 'block';
      lapelLEl.style.display = 'block';
      lapelREl.style.display = 'block';
      suitBtn1El.style.display = 'block';
      suitBtn2El.style.display = 'block';
      playerEl.querySelector('#player-visual').setAttribute('transform', 'scale(1, 1)');
    }
  }

  // Game Loop
  function gameLoop() {
    if (!state.modalOpen && !state.transitioning) {
      let mx = 0;
      let my = 0;

      if (state.keys.w || state.keys.up) my -= 1;
      if (state.keys.s || state.keys.down) my += 1;
      if (state.keys.a || state.keys.left) mx -= 1;
      if (state.keys.d || state.keys.right) mx += 1;

      state.isMoving = (mx !== 0 || my !== 0);

      if (state.isMoving) {
        const length = Math.sqrt(mx * mx + my * my);
        mx = (mx / length) * state.speed;
        my = (my / length) * state.speed;

        if (Math.abs(mx) > Math.abs(my)) {
          state.facing = mx > 0 ? 'right' : 'left';
        } else {
          state.facing = my > 0 ? 'down' : 'up';
        }
        updateCharacterFacing(state.facing);

        if (!checkCollision(state.x + mx, state.y)) {
          state.x += mx;
        }
        if (!checkCollision(state.x, state.y + my)) {
          state.y += my;
        }

        state.walkCycle += 0.22;
        const legSwing = Math.sin(state.walkCycle) * 7;
        const armSwing = Math.cos(state.walkCycle) * 6;
        const headBob = Math.abs(Math.sin(state.walkCycle)) * 1.5;

        legLEl.setAttribute('y', 14 + legSwing);
        shoeLEl.setAttribute('transform', `translate(0, ${legSwing})`);
        legREl.setAttribute('y', 14 - legSwing);
        shoeREl.setAttribute('transform', `translate(0, ${-legSwing})`);

        armLEl.setAttribute('transform', `translate(0, ${-armSwing})`);
        armREl.setAttribute('transform', `translate(0, ${armSwing})`);
        headEl.setAttribute('transform', `translate(0, ${-18 + headBob})`);
      } else {
        legLEl.setAttribute('y', 14);
        shoeLEl.removeAttribute('transform');
        legREl.setAttribute('y', 14);
        shoeREl.removeAttribute('transform');
        armLEl.removeAttribute('transform');
        armREl.removeAttribute('transform');
        headEl.setAttribute('transform', 'translate(0, -18)');
      }

      updateProximity();
    }

    playerEl.setAttribute('transform', `translate(${state.x}, ${state.y})`);

    requestAnimationFrame(gameLoop);
  }

  updateCharacterFacing('down');
  requestAnimationFrame(gameLoop);
})();
